//! Fresh records only: generated by the hash-pinned glibc loader in hosted CI.
use super::{acos, asin, atan, atan2, pow, tan};

#[test]
fn specials_and_identities() {
    for x in [0.0_f64, -0.0, f64::from_bits(1), -f64::from_bits(1)] {
        assert_eq!(atan(x).to_bits(), x.to_bits());
        assert_eq!(tan(x).to_bits(), x.to_bits());
        assert_eq!(asin(x).to_bits(), x.to_bits());
    }
    for x in [f64::INFINITY, f64::NEG_INFINITY, 2.0, -2.0] {
        assert_eq!(asin(x).to_bits(), 0x7ff8_0000_0000_0000);
        assert_eq!(acos(x).to_bits(), 0x7ff8_0000_0000_0000);
    }
    for b in [0x7ff0000000000001, 0xfff80000deadbeef, 0x7fffffffffffffff] {
        let x = f64::from_bits(b);
        for y in [
            atan(x),
            tan(x),
            asin(x),
            acos(x),
            atan2(x, 1.0),
            atan2(1.0, x),
        ] {
            assert_eq!(y.to_bits(), b | super::QUIET);
        }
    }
    assert_eq!(
        atan2(-0.0, -1.0).to_bits(),
        (-core::f64::consts::PI).to_bits()
    );
}

#[test]
#[ignore = "requires fresh glibc 2.39 records; see rust-glibc-libm workflow"]
fn reference_records() -> Result<(), String> {
    let path = std::env::var("KICAD_GLIBC_LIBM_REFERENCE").map_err(|e| e.to_string())?;
    let count = std::env::var("KICAD_GLIBC_LIBM_COUNT")
        .map_err(|e| e.to_string())?
        .parse::<usize>()
        .map_err(|e| e.to_string())?;
    let data = std::fs::read(path).map_err(|e| e.to_string())?;
    assert_eq!(data.len(), count * 56, "record count");
    let mut mismatches = [0_usize; 5];
    let names = ["atan", "atan2", "tan", "asin", "acos"];
    for row in data.chunks_exact(56) {
        let mut words = [0_u64; 7];
        for (w, b) in words.iter_mut().zip(row.chunks_exact(8)) {
            let mut a = [0_u8; 8];
            a.copy_from_slice(b);
            *w = u64::from_le_bytes(a);
        }
        let x = f64::from_bits(words[0]);
        let y = f64::from_bits(words[1]);
        let got = [atan(x), atan2(y, x), tan(x), asin(x), acos(x)].map(f64::to_bits);
        for i in 0..5 {
            if got[i] != words[i + 2] {
                if mismatches[i] < 10 {
                    println!(
                        "{} x {:016x} y {:016x}: got {:016x} want {:016x}",
                        names[i],
                        words[0],
                        words[1],
                        got[i],
                        words[i + 2]
                    );
                }
                mismatches[i] += 1;
            }
        }
    }
    for i in 0..5 {
        println!(
            "glibc_libm {}: {count} records, {} mismatches",
            names[i], mismatches[i]
        );
    }
    assert_eq!(mismatches, [0; 5]);
    Ok(())
}

// Values follow from e_pow.c's special branches and exact IEEE arithmetic
// alone (no recorded glibc result): signed zeros/infinities, NaN selection
// order, the SSE2 invalid NaN, exact powers of two and the subnormal and
// overflow edges.
#[test]
fn pow_special_branches() {
    let bits = |x: f64| x.to_bits();
    let snan = f64::from_bits(0x7ff4_0000_0000_0abc);
    let qnan = f64::from_bits(0xfff8_0000_dead_beef);
    // y == +-0 returns 1 unless x is signalling; x == 1 likewise for y.
    assert_eq!(bits(pow(qnan, 0.0)), bits(1.0));
    assert_eq!(bits(pow(snan, -0.0)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(pow(1.0, qnan)), bits(1.0));
    assert_eq!(bits(pow(1.0, snan)), 0x7ffc_0000_0000_0abc);
    // x + y: a NaN x wins over a NaN y (first SSE2 operand).
    assert_eq!(bits(pow(qnan, snan)), bits(qnan));
    assert_eq!(bits(pow(snan, qnan)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(pow(2.0, snan)), 0x7ffc_0000_0000_0abc);
    // A NaN x with a finite y: x*x, negated for an odd y, unchanged by 1/x2.
    assert_eq!(
        bits(pow(f64::from_bits(0xfff0_0000_0000_0001), 3.0)),
        0x7ff8_0000_0000_0001
    );
    assert_eq!(
        bits(pow(f64::from_bits(0xfff0_0000_0000_0001), -3.0)),
        0x7ff8_0000_0000_0001
    );
    assert_eq!(
        bits(pow(f64::from_bits(0xfff0_0000_0000_0001), 2.0)),
        0xfff8_0000_0000_0001
    );
    // Infinite y.
    assert_eq!(bits(pow(-1.0, f64::INFINITY)), bits(1.0));
    assert_eq!(bits(pow(0.5, f64::INFINITY)), bits(0.0));
    assert_eq!(bits(pow(2.0, f64::NEG_INFINITY)), bits(0.0));
    assert_eq!(bits(pow(2.0, f64::INFINITY)), bits(f64::INFINITY));
    assert_eq!(bits(pow(-0.5, f64::NEG_INFINITY)), bits(f64::INFINITY));
    // Zero and infinite x, signs from odd integer y.
    assert_eq!(bits(pow(-0.0, 3.0)), bits(-0.0));
    assert_eq!(bits(pow(-0.0, 2.0)), bits(0.0));
    assert_eq!(bits(pow(-0.0, -3.0)), bits(f64::NEG_INFINITY));
    assert_eq!(bits(pow(0.0, -0.5)), bits(f64::INFINITY));
    assert_eq!(bits(pow(f64::NEG_INFINITY, 3.0)), bits(f64::NEG_INFINITY));
    assert_eq!(bits(pow(f64::NEG_INFINITY, -3.0)), bits(-0.0));
    assert_eq!(bits(pow(f64::NEG_INFINITY, 0.5)), bits(f64::INFINITY));
    // Negative finite x with a non-integer y: (x - x) / (x - x).
    assert_eq!(bits(pow(-2.0, 0.5)), 0xfff8_0000_0000_0000);
    assert_eq!(bits(pow(-8.0, 1.0 / 3.0)), 0xfff8_0000_0000_0000);
    // |y| < 2^-65 and |y| >= 2^63.
    let tiny = f64::from_bits(0x3bd0_0000_0000_0000);
    assert_eq!(bits(pow(2.0, tiny)), bits(1.0 + tiny));
    assert_eq!(bits(pow(0.5, tiny)), bits(1.0 - tiny));
    assert_eq!(bits(pow(2.0, 2.0_f64.powi(63))), bits(f64::INFINITY));
    assert_eq!(bits(pow(2.0, -(2.0_f64.powi(63)))), bits(0.0));
    assert_eq!(bits(pow(-2.0, 2.0_f64.powi(63))), bits(f64::INFINITY));
    // Exact powers of two through the table path, specialcase and subnormals.
    for e in -1074..1024 {
        let want = if e >= -1022 {
            f64::from_bits(((e + 1023) as u64) << 52)
        } else {
            f64::from_bits(1 << (e + 1074))
        };
        assert_eq!(bits(pow(2.0, f64::from(e))), bits(want), "2^{e}");
        assert_eq!(
            bits(pow(-2.0, f64::from(e))),
            bits(if e % 2 != 0 { -want } else { want })
        );
    }
    assert_eq!(bits(pow(2.0, 1024.0)), bits(f64::INFINITY));
    assert_eq!(bits(pow(-2.0, 1025.0)), bits(f64::NEG_INFINITY));
    assert_eq!(bits(pow(2.0, -1076.0)), bits(0.0));
    assert_eq!(bits(pow(-2.0, -1077.0)), bits(-0.0));
    // A subnormal x is normalized before the logarithm.
    assert_eq!(bits(pow(f64::from_bits(1), 1.0)), 1);
    assert_eq!(bits(pow(f64::from_bits(1), 0.5)), bits(2.0_f64.powi(-537)));
    // Small exact integer powers of ten, as EDA_ANGLE::Round requests.
    let mut p = 1.0;
    for d in 0..=22 {
        assert_eq!(bits(pow(10.0, f64::from(d))), bits(p), "10^{d}");
        p *= 10.0;
    }
}

#[test]
#[ignore = "requires fresh glibc 2.39 pow records; see rust-glibc-libm workflow"]
fn pow_reference_records() -> Result<(), String> {
    let path = std::env::var("KICAD_GLIBC_LIBM_POW_REFERENCE").map_err(|e| e.to_string())?;
    let count = std::env::var("KICAD_GLIBC_LIBM_POW_COUNT")
        .map_err(|e| e.to_string())?
        .parse::<usize>()
        .map_err(|e| e.to_string())?;
    let data = std::fs::read(path).map_err(|e| e.to_string())?;
    assert_eq!(data.len(), count * 24, "record count");
    let mut mismatches = 0_usize;
    for row in data.chunks_exact(24) {
        let mut words = [0_u64; 3];
        for (w, b) in words.iter_mut().zip(row.chunks_exact(8)) {
            let mut a = [0_u8; 8];
            a.copy_from_slice(b);
            *w = u64::from_le_bytes(a);
        }
        let got = pow(f64::from_bits(words[0]), f64::from_bits(words[1])).to_bits();
        if got != words[2] {
            if mismatches < 10 {
                println!(
                    "pow x {:016x} y {:016x}: got {got:016x} want {:016x}",
                    words[0], words[1], words[2]
                );
            }
            mismatches += 1;
        }
    }
    println!("glibc_libm pow: {count} records, {mismatches} mismatches");
    assert_eq!(mismatches, 0);
    Ok(())
}

// Values follow from e_hypot.c's branches and exact IEEE arithmetic alone (no recorded
// glibc result): the non-finite branch's infinity and NaN selection, signed zeros, exact
// Pythagorean triples at every scaling branch, the 0x1p-54 shortcut and overflow.
#[test]
fn hypot_special_branches() {
    use crate::hypot::hypot;
    let bits = |x: f64| x.to_bits();
    let inf = f64::INFINITY;
    let snan = f64::from_bits(0x7ff4_0000_0000_0abc);
    let snan_neg = f64::from_bits(0xfff0_0000_0000_0001);
    let qnan = f64::from_bits(0xfff8_0000_dead_beef);
    let qnan2 = f64::from_bits(0x7ff8_0000_0000_0001);
    // An infinity wins over a quiet NaN, in either position and with either sign.
    for (x, y) in [
        (inf, qnan),
        (qnan, -inf),
        (-inf, 1.0),
        (0.0, inf),
        (-inf, inf),
    ] {
        assert_eq!(bits(hypot(x, y)), bits(inf));
    }
    // A signalling operand turns the infinity case into x + y.
    assert_eq!(bits(hypot(snan, inf)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(hypot(-inf, snan)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(hypot(inf, snan_neg)), 0xfff8_0000_0000_0001);
    // x + y: a NaN x wins quieted (first addsd operand), else the quieted NaN y.
    assert_eq!(bits(hypot(qnan, qnan2)), bits(qnan));
    assert_eq!(bits(hypot(qnan2, snan)), bits(qnan2));
    assert_eq!(bits(hypot(snan, qnan)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(hypot(-2.0, snan_neg)), 0xfff8_0000_0000_0001);
    assert_eq!(bits(hypot(qnan, -0.0)), bits(qnan));
    // Signed zeros and one zero operand.
    assert_eq!(bits(hypot(-0.0, -0.0)), bits(0.0));
    assert_eq!(bits(hypot(-0.0, -5.0)), bits(5.0));
    let min = f64::from_bits(1);
    assert_eq!(bits(hypot(-min, 0.0)), 1);
    // Exact triples through the common, scaled-down and scaled-up branches and subnormals.
    for k in [
        -1074_i64, -1060, -600, -470, -459, -100, 0, 100, 510, 511, 600, 1000,
    ] {
        // 2^k from its bits; powi(-1074) may round through 1 / 2^1074 = 0.
        let s = if k >= -1022 {
            f64::from_bits(((k + 1023) as u64) << 52)
        } else {
            f64::from_bits(1 << (k + 1074))
        };
        for (a, b, c) in [(3.0, 4.0, 5.0), (5.0, 12.0, 13.0), (20.0, 21.0, 29.0)] {
            assert_eq!(bits(hypot(a * s, -b * s)), bits(c * s), "{a} {b} 2^{k}");
            assert_eq!(bits(hypot(b * s, a * s)), bits(c * s));
        }
    }
    // ay <= ax * 0x1p-54 returns ax + ay (rounded to ax here).
    assert_eq!(bits(hypot(1.0, 2.0_f64.powi(-54))), bits(1.0));
    assert_eq!(bits(hypot(f64::MAX, 1.0)), bits(f64::MAX));
    // Overflow of the scaled kernel, and of ax + ay.
    assert_eq!(bits(hypot(f64::MAX, f64::MAX)), bits(inf));
    assert_eq!(
        bits(hypot(f64::MAX, f64::MAX * 2.0_f64.powi(-54))),
        bits(f64::MAX)
    );
}

/// Compares genuine 24-byte (x, y, f(x, y)) records from the locked libm.
fn binary_records(
    reference: &str,
    count: &str,
    name: &str,
    f: fn(f64, f64) -> f64,
) -> Result<(), String> {
    let path = std::env::var(reference).map_err(|e| e.to_string())?;
    let count = std::env::var(count)
        .map_err(|e| e.to_string())?
        .parse::<usize>()
        .map_err(|e| e.to_string())?;
    let data = std::fs::read(path).map_err(|e| e.to_string())?;
    assert_eq!(data.len(), count * 24, "record count");
    let mut mismatches = 0_usize;
    for row in data.chunks_exact(24) {
        let mut words = [0_u64; 3];
        for (w, b) in words.iter_mut().zip(row.chunks_exact(8)) {
            let mut a = [0_u8; 8];
            a.copy_from_slice(b);
            *w = u64::from_le_bytes(a);
        }
        let got = f(f64::from_bits(words[0]), f64::from_bits(words[1])).to_bits();
        if got != words[2] {
            if mismatches < 10 {
                println!(
                    "{name} x {:016x} y {:016x}: got {got:016x} want {:016x}",
                    words[0], words[1], words[2]
                );
            }
            mismatches += 1;
        }
    }
    println!("glibc_libm {name}: {count} records, {mismatches} mismatches");
    assert_eq!(mismatches, 0);
    Ok(())
}

#[test]
#[ignore = "requires fresh glibc 2.39 hypot records; see rust-glibc-libm workflow"]
fn hypot_reference_records() -> Result<(), String> {
    binary_records(
        "KICAD_GLIBC_LIBM_HYPOT_REFERENCE",
        "KICAD_GLIBC_LIBM_HYPOT_COUNT",
        "hypot",
        crate::hypot::hypot,
    )
}

// s_fma.c's special-operand returns in the locked body's SSE2 operand order: x * y keeps x's
// NaN over y's, then the product's NaN (or its invalid indefinite) over z's.
#[test]
fn fma_special_branches() {
    use super::fma;
    let bits = f64::to_bits;
    let inf = f64::INFINITY;
    let qa = f64::from_bits(0x7ff8_0000_0000_1234);
    let qb = f64::from_bits(0xfff8_0000_0000_00bb);
    let sc = f64::from_bits(0x7ff4_0000_0000_0abc);
    assert_eq!(bits(fma(inf, 0.0, qa)), 0xfff8_0000_0000_0000);
    assert_eq!(bits(fma(qa, qb, 1.0)), bits(qa));
    assert_eq!(bits(fma(qb, qa, qa)), bits(qb));
    assert_eq!(bits(fma(1.0, sc, qa)), 0x7ffc_0000_0000_0abc);
    assert_eq!(bits(fma(1.0, 2.0, sc)), 0x7ffc_0000_0000_0abc);
    // z == 0 with nonzero factors returns x * y.
    assert_eq!(bits(fma(qa, qb, 0.0)), bits(qa));
    assert_eq!(bits(fma(inf, -inf, 0.0)), bits(-inf));
    assert_eq!(bits(fma(2.0, 3.0, -inf)), bits(-inf));
    assert_eq!(bits(fma(inf, 1.0, -inf)), 0xfff8_0000_0000_0000);
    // Exact zero results: signs as IEEE round-to-nearest gives them.
    assert_eq!(bits(fma(3.0, 5.0, -15.0)), 0);
    assert_eq!(bits(fma(-0.0, 5.0, -0.0)), bits(-0.0));
    assert_eq!(bits(fma(0.0, -5.0, 0.0)), 0);
    // The single rounding: (1 + 2^-52)^2 - 1 keeps the 2^-104 term.
    let x = 1.0 + f64::EPSILON;
    assert_eq!(
        fma(x, x, -1.0),
        2.0 * f64::EPSILON + f64::EPSILON * f64::EPSILON
    );
    // Overflow, the tiny product and subnormal results.
    assert_eq!(fma(f64::MAX, 2.0, -f64::MAX), f64::MAX);
    assert_eq!(fma(f64::MAX, f64::MAX, 1.0), inf);
    let tiny = f64::from_bits(1);
    assert_eq!(fma(tiny, 0.5, 0.0), 0.0);
    assert_eq!(bits(fma(-tiny, 0.5, 0.0)), bits(-0.0));
    assert_eq!(fma(tiny, tiny, 1.0), 1.0);
    assert_eq!(fma(2.0_f64.powi(-537), 2.0_f64.powi(-537), 0.0), tiny);
}

/// Compares genuine 32-byte (x, y, z, fma(x, y, z)) records from the locked libm.
#[test]
#[ignore = "requires fresh glibc 2.39 fma records; see rust-glibc-libm workflow"]
fn fma_reference_records() -> Result<(), String> {
    let path = std::env::var("KICAD_GLIBC_LIBM_FMA_REFERENCE").map_err(|e| e.to_string())?;
    let count = std::env::var("KICAD_GLIBC_LIBM_FMA_COUNT")
        .map_err(|e| e.to_string())?
        .parse::<usize>()
        .map_err(|e| e.to_string())?;
    let data = std::fs::read(path).map_err(|e| e.to_string())?;
    assert_eq!(data.len(), count * 32, "record count");
    let mut mismatches = 0_usize;
    for row in data.chunks_exact(32) {
        let mut words = [0_u64; 4];
        for (w, b) in words.iter_mut().zip(row.chunks_exact(8)) {
            let mut a = [0_u8; 8];
            a.copy_from_slice(b);
            *w = u64::from_le_bytes(a);
        }
        let got = super::fma(
            f64::from_bits(words[0]),
            f64::from_bits(words[1]),
            f64::from_bits(words[2]),
        )
        .to_bits();
        if got != words[3] {
            if mismatches < 10 {
                println!(
                    "fma x {:016x} y {:016x} z {:016x}: got {got:016x} want {:016x}",
                    words[0], words[1], words[2], words[3]
                );
            }
            mismatches += 1;
        }
    }
    println!("glibc_libm fma: {count} records, {mismatches} mismatches");
    assert_eq!(mismatches, 0);
    Ok(())
}
